import type { Metadata } from "next";
import { getSupportPrograms } from "@/src/data/programs";
import { PageHeader } from "@/src/components/layout";
import { ProgramsExplorer } from "./_components/ProgramsExplorer";

export const metadata: Metadata = {
  title: "에너지 절감 지원사업",
};

function readInitialTag(value: string | string[] | undefined): string | null {
  if (typeof value === "string") return value;
  if (Array.isArray(value) && value.length > 0) return value[0];
  return null;
}

/**
 * Server shell for the support-programs list. Awaits `searchParams` for the
 * `?tag=` deep link, fetches every fixture program (all six), and hands them
 * to the `ProgramsExplorer` client island for tag filtering, the
 * notification switch/toast, and the leave-confirmation dialog.
 */
export default async function ProgramsPage({ searchParams }: PageProps<"/programs">) {
  const resolvedSearchParams = await searchParams;
  const initialTag = readInitialTag(resolvedSearchParams.tag);

  const programs = await getSupportPrograms();

  return (
    <main>
      <PageHeader
        eyebrow="정부 · 지자체 · 공공기관"
        title="에너지 절감 지원사업"
        description="건물의 단열, 창호, 재생에너지 설비 개선에 활용할 수 있는 지원사업을 태그로 찾아보고, 신청 페이지로 바로 이동해 보세요."
      />

      <div className="eco-container pb-[var(--space-12)]">
        <ProgramsExplorer programs={programs} initialTag={initialTag} />
      </div>
    </main>
  );
}
