import Link from "next/link";

export interface SectionHeaderAction {
  label: string;
  href: string;
}

export interface SectionHeaderProps {
  title: string;
  description?: string;
  action?: SectionHeaderAction;
  /** Heading level for the title. Defaults to `h2`. */
  as?: "h2" | "h3";
}

/** Heading for a page section, with an optional description and "see more" link. */
export function SectionHeader({ title, description, action, as = "h2" }: SectionHeaderProps) {
  const Heading = as;
  return (
    <div className="flex flex-col gap-[var(--space-2)] sm:flex-row sm:items-end sm:justify-between">
      <div>
        <Heading className="eco-heading">{title}</Heading>
        {description ? (
          <p className="mt-[var(--space-1)] text-[length:var(--text-body-size)] text-[var(--text-muted)]">
            {description}
          </p>
        ) : null}
      </div>
      {action ? (
        <Link
          href={action.href}
          className="inline-flex items-center gap-[var(--space-1)] text-[length:var(--text-label-size)] font-medium text-[var(--text-link)] hover:underline"
        >
          {action.label}
          <span aria-hidden="true">→</span>
        </Link>
      ) : null}
    </div>
  );
}
